using System.Linq;
using SharpCompute.Samples.Shaders;

namespace SharpCompute.Tests;

/// <summary>
/// The M2.5 Shadertoy ports: each one, generated by the source generator and dispatched through
/// <c>ForEach</c>, renders a real picture (not blank, black, or a flat color) at 256×144.
/// </summary>
public class GalleryPortTests
{
    /// <summary>The ported shaders, in gallery order (HelloWorld has its own CPU-reference test).</summary>
    private static readonly string[] PortNames =
    [
        "ColorfulInfinity",
        "FourColorGradient",
        "FractalTiling",
        "Octagrams",
        "TwoTiledTruchet",
        "MengerJourney",
        "ProteanClouds",
        "TerracedHills",
        "PyramidPattern",
        "ExtrudedTruchetPattern",
        "TriangleGridContouring",
    ];

    public static TheoryData<string> Ports => new(PortNames);

    [Fact]
    public void EveryPort_IsRegisteredAfterHelloWorld_InOrder()
    {
        string[] names = Gallery.All.Select(static s => s.Name).ToArray();
        int start = System.Array.IndexOf(names, "HelloWorld") + 1;

        Assert.Equal(PortNames, names.Skip(start).Take(PortNames.Length));
    }

    [MetalTheory]
    [MemberData(nameof(Ports))]
    public void Port_RendersANonUniformOpaqueImage(string name)
    {
        GalleryShader shader = Gallery.All.Single(s => s.Name == name);
        GraphicsDevice device = GraphicsDevice.GetDefault();
        using ReadWriteTexture2D<Rgba32> texture = device.AllocateReadWriteTexture2D<Rgba32>(256, 144);

        shader.Render(device, texture, 1.5f);

        Rgba32[] pixels = texture.ToArray();

        Assert.True(pixels.Distinct().Count() >= 16, $"{name} rendered fewer than 16 distinct colors.");
        Assert.Contains(pixels, static p => p.R != 0 || p.G != 0 || p.B != 0);
        // Shadertoy ignores alpha, but the gallery writes it to the PNG: a port must be opaque.
        Assert.All(pixels, static p => Assert.Equal(255, p.A));
    }
}
